import {validateCatalog} from './search-core.mjs';
export async function loadCatalog(fetcher=fetch){const response=await fetcher('./catalog.json',{cache:'no-store',redirect:'error',credentials:'omit',signal:AbortSignal.timeout(15000)});if(!response.ok||!response.body)throw new Error('Catalog request failed');let size=0;const chunks=[];for await(const chunk of response.body){size+=chunk.length;if(size>2000000)throw new Error('Oversized catalog');chunks.push(chunk);}const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}return validateCatalog(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)));}
